import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import io from 'socket.io-client';

const JoinGame = () => {
  const navigate = useNavigate();
  const [socket, setSocket] = useState(null);
  const [playerName, setPlayerName] = useState('');
  const [isConnected, setIsConnected] = useState(false);
  const [isJoined, setIsJoined] = useState(false);
  const [isModerator, setIsModerator] = useState(false);
  const [playerRole, setPlayerRole] = useState(null);
  const [playerList, setPlayerList] = useState([]);
  const [gameStarted, setGameStarted] = useState(false);
  const [roundStarted, setRoundStarted] = useState(false);
  const [moderatorConnected, setModeratorConnected] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [roleAssignments, setRoleAssignments] = useState([]);
  const [gameConfig, setGameConfig] = useState(null);
  const [deadPlayersCount, setDeadPlayersCount] = useState(0);
  const [isDead, setIsDead] = useState(false);
  const [allRoles, setAllRoles] = useState([]);

  useEffect(() => {
    // Load game configuration from session storage
    const config = sessionStorage.getItem('werewolfConfig');
    if (config) {
      setGameConfig(JSON.parse(config));
    }

    // Connect to socket server
    const newSocket = io(process.env.NODE_ENV === 'production' ? window.location.origin : 'http://localhost:3001');
    setSocket(newSocket);

    newSocket.on('connect', () => {
      setIsConnected(true);
      setError('');
    });

    newSocket.on('disconnect', () => {
      setIsConnected(false);
      setError('Disconnected from server');
    });

    newSocket.on('joinSuccess', (data) => {
      setIsJoined(true);
      setIsModerator(data.isModerator);
      setSuccess(data.isModerator ? 'Joined as Moderator' : `Joined as ${data.name}`);
      setError('');
      
      // If moderator, request current player list and game state
      if (data.isModerator) {
        newSocket.emit('getPlayerList');
      }
    });

    newSocket.on('error', (message) => {
      setError(message);
      setSuccess('');
    });

    newSocket.on('playerListUpdate', (data) => {
      console.log('PlayerListUpdate received:', { roundStarted: data.roundStarted, gameStarted: data.gameStarted });
      setPlayerList(data.players);
      setGameStarted(data.gameStarted);
      setRoundStarted(data.roundStarted || false);
      setModeratorConnected(data.moderatorConnected);
      setDeadPlayersCount(data.deadPlayersCount || 0);
      
      // Ensure moderator status is preserved - if we're connected and moderator is connected,
      // and our name is 'moderator' (case insensitive), we should be the moderator
      if (isJoined && playerName.toLowerCase() === 'moderator' && data.moderatorConnected) {
        setIsModerator(true);
      }
    });

    newSocket.on('roleAssigned', (data) => {
      setPlayerRole(data.role);
      setSuccess('Role assigned! Game starting...');
    });

    newSocket.on('allRolesAssigned', (assignments) => {
      setRoleAssignments(assignments);
      if (assignments.length > 0) {
        // Check if this is from a fresh assignment or reconnection
        const hasCurrentAssignments = roleAssignments.length > 0;
        setSuccess(hasCurrentAssignments ? 'All roles assigned successfully!' : 'Reconnected - showing current game state');
      }
    });

    newSocket.on('gameReset', () => {
      setPlayerRole(null);
      setRoleAssignments([]);
      setGameStarted(false);
      setRoundStarted(false);
      setIsDead(false);
      setAllRoles([]);
      setDeadPlayersCount(0);
      setSuccess('Game has been reset - all players revived');
    });

    newSocket.on('roundStarted', () => {
      console.log('Received roundStarted event');
      setRoundStarted(true);
      setSuccess('Round has started!');
    });

    newSocket.on('playerDied', (data) => {
      setIsDead(true);
      setAllRoles(data.allRoles);
      setSuccess('You have been eliminated! You can now see all roles.');
    });

    newSocket.on('playerKilled', (data) => {
      setSuccess(`${data.playerName} has been eliminated!`);
    });

    newSocket.on('playerRevived', (data) => {
      if (data.role) {
        // This player was revived
        setIsDead(false);
        setAllRoles([]);
        setSuccess('You have been revived!');
      } else {
        // Another player was revived
        setSuccess(`${data.playerName} has been revived!`);
      }
    });

    newSocket.on('moderatorStatusConfirmed', (data) => {
      setIsModerator(true);
      console.log('Moderator status confirmed after reset');
    });

    return () => {
      newSocket.close();
    };
  }, []);

  const handleJoin = (e) => {
    e.preventDefault();
    if (!playerName.trim()) {
      setError('Please enter a name');
      return;
    }
    
    if (socket && isConnected) {
      socket.emit('join', playerName.trim());
    } else {
      setError('Not connected to server');
    }
  };

  const handleAssignRoles = () => {
    if (!gameConfig) {
      setError('No game configuration found. Please go back to setup.');
      return;
    }

    if (playerList.length < 4) {
      setError(`Need at least 4 players to start. Currently have ${playerList.length}.`);
      return;
    }

    if (playerList.length > 15) {
      setError(`Maximum 15 players supported. Currently have ${playerList.length}.`);
      return;
    }

    const totalSpecialRoles = (gameConfig.specialRoles || []).length + (gameConfig.tiAlbertCount || 1);
    if (totalSpecialRoles >= playerList.length) {
      setError(`Too many special roles (${totalSpecialRoles}) for ${playerList.length} players. Need at least 1 regular villager.`);
      return;
    }

    // Clear previous role assignments
    setRoleAssignments([]);
    setError('');

    const config = {
      playerCount: playerList.length, // Use actual number of joined players
      tiAlbertCount: gameConfig.tiAlbertCount || 1, // Fallback to 1 if missing
      specialRoles: gameConfig.specialRoles || []
    };

    console.log('Sending config to backend:', config);
    socket.emit('assignRoles', config);
  };

  const handleResetGame = () => {
    if (socket) {
      socket.emit('resetGame');
      // Clear local state
      setRoleAssignments([]);
      setGameStarted(false);
      setRoundStarted(false);
      setIsDead(false);
      setAllRoles([]);
      setDeadPlayersCount(0);
      setError('');
      setSuccess('');
    }
  };

  const handleStartRound = () => {
    if (socket && gameStarted) {
      socket.emit('startRound');
    } else {
      setError('Assign roles first before starting a round');
    }
  };

  const handleKillPlayer = (playerId) => {
    if (socket && roundStarted) {
      socket.emit('killPlayer', playerId);
    } else {
      setError('Start a round first before killing players');
    }
  };

  const handleRevivePlayer = (playerId) => {
    if (socket) {
      socket.emit('revivePlayer', playerId);
    }
  };

  const handleBackToSetup = () => {
    navigate('/TiAlbertSetup');
  };

  const handleBackToMenu = () => {
    navigate('/');
  };

  const getConnectionStatus = () => {
    if (!isConnected) return { text: 'Disconnected', class: 'status-disconnected' };
    if (!isJoined) return { text: 'Connected', class: 'status-connected' };
    if (isJoined && !gameStarted) return { text: 'Waiting', class: 'status-waiting' };
    return { text: 'In Game', class: 'status-connected' };
  };

  const status = getConnectionStatus();

  return (
    <div className="container">
      <button 
        className="back-button"
        onClick={handleBackToMenu}
        title="Back to Main Menu"
      >
        ←
      </button>
      
      <div className="card">
        <h1 className="title">Join Werewolf Game</h1>
        
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          marginBottom: '20px'
        }}>
          <span className={`status-indicator ${status.class}`}></span>
          <span style={{ fontWeight: '500' }}>Status: {status.text}</span>
        </div>

        {error && <div className="error">{error}</div>}
        {success && <div className="success">{success}</div>}

        {!isJoined ? (
          <form onSubmit={handleJoin}>
            <div className="form-group">
              <label className="form-label">Enter Your Name</label>
              <input
                type="text"
                className="input"
                value={playerName}
                onChange={(e) => setPlayerName(e.target.value)}
                placeholder="Your name..."
                disabled={!isConnected}
              />
              <div style={{ fontSize: '0.9rem', color: '#718096', marginTop: '5px' }}>
                Enter "moderator" to access game controls
              </div>
            </div>
            
            <button
              type="submit"
              className="button"
              disabled={!isConnected || !playerName.trim()}
            >
              {isConnected ? '🎮 Join Game' : '⏳ Connecting...'}
            </button>
          </form>
        ) : (
          <div>
            {/* Player Role Display - Enhanced Card */}
            {playerRole && !isDead && (
              <div style={{
                marginBottom: '24px',
                padding: '20px',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                borderRadius: '16px',
                boxShadow: '0 8px 32px rgba(0,0,0,0.12)',
                color: 'white',
                position: 'relative',
                overflow: 'hidden'
              }}>
                {/* Background Pattern */}
                <div style={{
                  position: 'absolute',
                  top: 0,
                  right: 0,
                  width: '120px',
                  height: '120px',
                  background: 'rgba(255,255,255,0.1)',
                  borderRadius: '50%',
                  transform: 'translate(40px, -40px)'
                }}></div>
                
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px', position: 'relative' }}>
                  {/* Role Icon */}
                  <div style={{
                    width: '60px',
                    height: '60px', 
                    borderRadius: '12px',
                    background: 'rgba(255,255,255,0.2)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '24px',
                    flexShrink: 0
                  }}>
                    {playerRole.name === 'Ti Albert' ? '🐺' : 
                     playerRole.name === 'Vilazwas' ? '👥' :
                     playerRole.name === 'Bhai looké' ? '👁️' :
                     playerRole.name === 'Cliffeurd' ? '⚕️' :
                     playerRole.name === 'Agwa' ? '🛡️' :
                     playerRole.name === 'Longanis' ? '🏹' :
                     playerRole.name === 'Tifi' ? '🧪' :
                     playerRole.name === 'Sefvilaz' ? '👑' :
                     playerRole.name === 'Voler' ? '🎭' : '👤'}
                  </div>
                  
                  <div style={{ flex: 1 }}>
                    <h3 style={{ 
                      margin: 0, 
                      fontSize: '1.4rem', 
                      fontWeight: '600',
                      marginBottom: '4px'
                    }}>
                      {playerRole.name}
                    </h3>
                    <p style={{ 
                      margin: 0, 
                      fontSize: '0.9rem', 
                      opacity: 0.9,
                      lineHeight: '1.4'
                    }}>
                      {playerRole.description}
                    </p>
                  </div>
                </div>
              </div>
            )}

            {/* Dead Player - All Roles Display */}
            {isDead && allRoles.length > 0 && (
              <div style={{
                marginBottom: '24px',
                padding: '20px',
                background: 'linear-gradient(135deg, #ff6b6b 0%, #ee5a52 100%)',
                borderRadius: '16px',
                boxShadow: '0 8px 32px rgba(255,107,107,0.3)',
                color: 'white'
              }}>
                <h3 style={{ 
                  margin: 0,
                  marginBottom: '16px',
                  textAlign: 'center',
                  fontSize: '1.2rem',
                  fontWeight: '600'
                }}>
                  💀 You are eliminated - All Roles Revealed
                </h3>
                <div style={{ display: 'grid', gap: '12px' }}>
                  {allRoles.map((playerRole, index) => (
                    <div key={index} style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      padding: '12px 16px',
                      backgroundColor: 'rgba(255,255,255,0.15)',
                      borderRadius: '8px',
                      opacity: playerRole.isAlive ? 1 : 0.6,
                      backdropFilter: 'blur(10px)'
                    }}>
                      <span style={{
                        fontWeight: '500',
                        textDecoration: playerRole.isAlive ? 'none' : 'line-through',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '8px'
                      }}>
                        <span style={{ fontSize: '1.2rem' }}>
                          {playerRole.role === 'Ti Albert' ? '🐺' : 
                           playerRole.role === 'Vilazwas' ? '�' :
                           playerRole.role === 'Bhai looké' ? '👁️' :
                           playerRole.role === 'Cliffeurd' ? '⚕️' :
                           playerRole.role === 'Agwa' ? '🛡️' :
                           playerRole.role === 'Longanis' ? '🏹' :
                           playerRole.role === 'Tifi' ? '🧪' :
                           playerRole.role === 'Sefvilaz' ? '👑' :
                           playerRole.role === 'Voler' ? '🎭' : '👤'}
                        </span>
                        {playerRole.isAlive ? '' : '💀 '}{playerRole.name}
                      </span>
                      <span style={{
                        fontWeight: '600',
                        fontSize: '0.9rem'
                      }}>
                        {playerRole.role}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Moderator Controls - Clean Card Layout */}
            {isModerator && (
              <div style={{
                marginBottom: '24px',
                background: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',
                borderRadius: '16px',
                padding: '24px',
                boxShadow: '0 8px 32px rgba(79,172,254,0.3)',
                color: 'white'
              }}>
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  gap: '12px', 
                  marginBottom: '20px' 
                }}>
                  <div style={{
                    width: '40px',
                    height: '40px',
                    borderRadius: '8px',
                    background: 'rgba(255,255,255,0.2)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '20px'
                  }}>
                    🎯
                  </div>
                  <h3 style={{ margin: 0, fontSize: '1.3rem', fontWeight: '600' }}>
                    Moderator Controls
                  </h3>
                </div>
                
                {/* Game Info */}
                {gameConfig && (
                  <div style={{ 
                    marginBottom: '20px', 
                    padding: '12px 16px',
                    backgroundColor: 'rgba(255,255,255,0.15)',
                    borderRadius: '8px',
                    fontSize: '0.9rem'
                  }}>
                    <strong>{playerList.length} players</strong> • <strong>{gameConfig.tiAlbertCount}</strong> Ti Albert • <strong>{gameConfig.specialRoles.length}</strong> special roles
                  </div>
                )}

                {/* Action Buttons Grid */}
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '16px' }}>
                  <button
                    className="button"
                    onClick={handleAssignRoles}
                    disabled={!gameConfig || playerList.length < 4 || gameStarted}
                    style={{ 
                      backgroundColor: 'rgba(255,255,255,0.2)',
                      border: '1px solid rgba(255,255,255,0.3)',
                      color: 'white',
                      fontWeight: '500',
                      padding: '12px 16px',
                      borderRadius: '8px',
                      cursor: (!gameConfig || playerList.length < 4 || gameStarted) ? 'not-allowed' : 'pointer',
                      opacity: (!gameConfig || playerList.length < 4 || gameStarted) ? 0.6 : 1
                    }}
                  >
                    🎲 Assign Roles
                  </button>
                  
                  <button
                    className="button"
                    onClick={handleResetGame}
                    disabled={!gameStarted}
                    style={{ 
                      backgroundColor: 'rgba(255,255,255,0.2)',
                      border: '1px solid rgba(255,255,255,0.3)',
                      color: 'white',
                      fontWeight: '500',
                      padding: '12px 16px',
                      borderRadius: '8px',
                      cursor: !gameStarted ? 'not-allowed' : 'pointer',
                      opacity: !gameStarted ? 0.6 : 1
                    }}
                  >
                    🔄 Reset
                  </button>
                </div>

                {/* Back to Setup */}
                <button
                  className="button"
                  onClick={handleBackToSetup}
                  style={{ 
                    width: '100%',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    border: '1px solid rgba(255,255,255,0.2)',
                    color: 'rgba(255,255,255,0.8)',
                    fontWeight: '400',
                    padding: '10px 16px',
                    borderRadius: '6px',
                    fontSize: '0.9rem',
                    marginBottom: '16px'
                  }}
                >
                  ⚙️ Back to Setup
                </button>

                {/* Start Round Button */}
                <button
                  className="button"
                  onClick={handleStartRound}
                  disabled={!gameStarted || roundStarted}
                  style={{ 
                    width: '100%',
                    backgroundColor: (!gameStarted || roundStarted) ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.25)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: 'white',
                    fontWeight: '600',
                    padding: '14px 20px',
                    borderRadius: '8px',
                    fontSize: '1rem',
                    cursor: (!gameStarted || roundStarted) ? 'not-allowed' : 'pointer',
                    opacity: !gameStarted ? 0.6 : 1,
                    marginBottom: '12px'
                  }}
                >
                  {!gameStarted ? '⏳ Assign Roles First' : 
                   roundStarted ? '⏸️ Round in Progress' : 
                   '▶️ Start Round'}
                </button>

                {/* Stats */}
                {gameStarted && deadPlayersCount > 0 && (
                  <div style={{ 
                    padding: '8px 12px',
                    backgroundColor: 'rgba(255,107,107,0.2)',
                    borderRadius: '6px',
                    textAlign: 'center',
                    fontSize: '0.85rem'
                  }}>
                    💀 {deadPlayersCount} player{deadPlayersCount > 1 ? 's' : ''} eliminated
                  </div>
                )}


              </div>
            )}

            {/* Players & Roles List */}
            <div className="player-list">
              <h3 style={{ 
                marginBottom: '15px', 
                color: '#4a5568',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between'
              }}>
                👥 Players {gameStarted && '& Roles'} ({playerList.length})
                <span style={{ fontSize: '0.9rem', color: '#718096' }}>
                  {playerList.length < 4 ? `Need ${4 - playerList.length} more` : 'Ready!'}
                </span>
              </h3>
              
              {playerList.length === 0 ? (
                <div style={{ 
                  textAlign: 'center', 
                  color: '#718096',
                  fontSize: '0.9rem',
                  padding: '20px 0'
                }}>
                  Waiting for players to join...
                </div>
              ) : (
                playerList.map((player, index) => {
                  // Find the role for this player from roleAssignments (for moderator)
                  const playerRole = roleAssignments.find(assignment => assignment.name === player.name);
                  
                  return (
                    <div key={index} className="player-item" style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      padding: '12px',
                      backgroundColor: player.isDead ? '#fed7d7' : '#f7fafc',
                      opacity: player.isDead ? 0.7 : 1,
                      borderRadius: '8px',
                      marginBottom: '8px',
                      border: '1px solid #e2e8f0'
                    }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flex: 1 }}>
                        <span className="player-name" style={{
                          textDecoration: player.isDead ? 'line-through' : 'none',
                          fontWeight: '500',
                          minWidth: '80px'
                        }}>
                          {player.isDead ? '💀' : ''} {player.name}
                        </span>
                        
                        {/* Role Display (for moderator when roles are assigned) */}
                        {isModerator && playerRole ? (
                          <span style={{
                            fontSize: '0.9rem',
                            color: playerRole.role === 'Ti Albert' ? '#e53e3e' : '#38a169',
                            fontWeight: '500',
                            backgroundColor: 'white',
                            padding: '4px 8px',
                            borderRadius: '4px',
                            border: `1px solid ${playerRole.role === 'Ti Albert' ? '#fed7d7' : '#c6f6d5'}`,
                            flex: 1
                          }}>
                            {playerRole.role}
                          </span>
                        ) : (
                          <span style={{ 
                            fontSize: '0.8rem',
                            color: player.hasRole ? '#38a169' : '#718096',
                            flex: 1
                          }}>
                            {player.hasRole ? '✓ Ready' : '⏳ Waiting'}
                          </span>
                        )}
                      </div>
                      
                      {/* Moderator Kill/Revive Controls */}
                      {isModerator && roundStarted && player.hasRole && (
                        <div style={{ display: 'flex', gap: '5px' }}>
                          {player.isDead ? (
                            <button
                              className="button"
                              onClick={() => handleRevivePlayer(player.id)}
                              style={{
                                fontSize: '0.7rem',
                                padding: '4px 8px',
                                backgroundColor: '#38a169',
                                borderColor: '#38a169'
                              }}
                            >
                              ↻ Revive
                            </button>
                          ) : (
                            <button
                              className="button"
                              onClick={() => handleKillPlayer(player.id)}
                              style={{
                                fontSize: '0.7rem',
                                padding: '4px 8px',
                                backgroundColor: '#e53e3e',
                                borderColor: '#e53e3e'
                              }}
                            >
                              ⚔️ Kill
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  );
                })
              )}
            </div>

            {/* Game Status */}
            <div style={{ 
              marginTop: '20px',
              padding: '15px',
              background: gameStarted ? 'rgba(56, 161, 105, 0.1)' : 'rgba(237, 137, 54, 0.1)',
              borderRadius: '10px',
              textAlign: 'center'
            }}>
              {gameStarted ? (
                <div style={{ color: '#38a169' }}>
                  <strong>🎉 Game Started!</strong>
                  <div style={{ fontSize: '0.9rem', marginTop: '5px' }}>
                    All roles have been assigned
                    {roundStarted && (
                      <div style={{ marginTop: '5px', color: '#2d3748' }}>
                        ⚔️ Round in progress
                        {deadPlayersCount > 0 && ` • ${deadPlayersCount} eliminated`}
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div style={{ color: '#c05621' }}>
                  <strong>⏳ Waiting to Start</strong>
                  <div style={{ fontSize: '0.9rem', marginTop: '5px' }}>
                    {!moderatorConnected && 'Waiting for moderator to join...'}
                    {moderatorConnected && playerList.length < 4 && 
                      `Need ${4 - playerList.length} more players (minimum 4)`}
                    {moderatorConnected && playerList.length >= 4 && 
                      'Ready! Moderator can assign roles.'}
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default JoinGame;
